def commit_problems(msg: str) -> list[str]:
    first = msg.split('\n')[0]
    if not first.strip():
        return ['empty']
    p = []
    if len(first) > 72:
        p.append('too long')
    if first.endswith('.'):
        p.append('full stop')
    if not first[0].isupper():
        p.append('capital')
    return p
